// One line per file for the execution log (and for anyone checking the run).
const prepared = $('Prepare Files').all().map(i => i.json);
const committed = $('Changed Files').all().map(i => i.json);
const results = $input.all().map(i => i.json);
const blocked = prepared.filter(f => f.blocked).map(f => `${f.path}: held back (${f.findings.join(', ')})`);
const failed = results.filter(r => r.error || (r.statusCode && r.statusCode >= 300)).map((r, i) => `${committed[i]?.path}: ${JSON.stringify(r.error || r.body).slice(0, 200)}`);
const summary = { checked: prepared.length, committed: committed.map(c => `${c.action} ${c.path}`), unchanged: prepared.length - committed.length - blocked.length, blocked, failed };
if (blocked.length || failed.length) throw new Error('GitHub backup incomplete: ' + JSON.stringify({ blocked, failed }));
return [{ json: summary }];

// Settings come from the summers.datastore.config.keys data table: { CATEGORY: { key: value } }.
const parse = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (/^(true|false)$/i.test(s)) return s.toLowerCase() === 'true';
  if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s);
  if (/^[\[{]/.test(s)) { try { return JSON.parse(s); } catch (e) { /* keep as text */ } }
  return s;
};
const cfg = {};
for (const { json: r } of $input.all()) {
  if (!r || !r.category || !r.key) continue;
  (cfg[r.category] ||= {})[r.key] = parse(r.value);
}
// Fail loudly if a required setting is missing, rather than running with a guess.
const REQUIRED = ["GITHUB_CONFIG.owner", "GITHUB_CONFIG.repo", "GITHUB_CONFIG.branch", "GITHUB_CONFIG.workflows_path", "GITHUB_CONFIG.tag_filter", "GITHUB_CONFIG.block_on_sensitive"];
const missing = REQUIRED.filter(p => { const [c, k] = p.split('.'); const v = cfg[c]?.[k]; return v === undefined || v === null || v === ''; });
if (missing.length) throw new Error('Missing settings in summers.datastore.config.keys: ' + missing.join(', '));
return [{ json: { cfg } }];

// Compare each prepared file with what is already in GitHub; keep only new or changed files.
const prepared = $('Prepare Files').all();
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
const out = [];
$input.all().forEach((it, i) => {
  const f = prepared[i]?.json;
  if (!f || f.blocked) return;
  const r = it.json || {};
  const status = r.statusCode ?? (r.body ? 200 : 404);
  const body = r.body ?? r;
  if (status !== 200 && status !== 404) throw new Error(`GitHub read failed for ${f.path}: HTTP ${status} ${JSON.stringify(body).slice(0, 200)}`);
  const existing = status === 200 && body.content ? Buffer.from(String(body.content).replace(/\n/g, ''), 'base64').toString('utf8') : null;
  if (existing === f.content) return;                       // unchanged
  out.push({ json: { path: f.path, name: f.name, sha: status === 200 ? body.sha : undefined,
                     content_b64: b64(f.content), action: existing === null ? 'add' : 'update' } });
});
const blocked = prepared.filter(p => p.json.blocked).map(p => `${p.json.path} (${p.json.findings.join(', ')})`);
if (!out.length && blocked.length) throw new Error('GitHub backup: nothing to commit, but files were held back: ' + blocked.join('; '));
return out;

// Turn each n8n workflow into a clean, reviewable JSON file for the public GitHub repo.
// Run-time fields are dropped, pinned test data is never included, and any file that looks like it
// contains an email address or a secret is held back (and reported) instead of being published.
const G = $('Build Config').first().json.cfg.GITHUB_CONFIG;
const CONFIG = {
  PATH: String(G.workflows_path || 'workflows').replace(/\/+$/, ''),
  BLOCK_ON_SENSITIVE: G.block_on_sensitive !== false,
  EXCLUDE_TAGS: (Array.isArray(G.exclude_tags) ? G.exclude_tags : ['Test']).map(t => String(t).toLowerCase()),
  ALLOWED_EMAIL_DOMAINS: (Array.isArray(G.allowed_email_domains) ? G.allowed_email_domains : []).map(d => String(d).toLowerCase()),
};
const SENSITIVE = [
  { what: 'email address', re: /[A-Za-z0-9._%+-]+@([A-Za-z0-9.-]+\.[A-Za-z]{2,})/g, email: true },
  { what: 'bearer token', re: /Bearer\s+[A-Za-z0-9._~+\/-]{20,}/g },
  { what: 'private key', re: /-----BEGIN [A-Z ]*PRIVATE KEY-----/g },
  { what: 'GitHub token', re: /gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,}/g },
  { what: 'API key literal', re: /"(api[_-]?key|apikey|secret|password|client_secret)"\s*:\s*"[^"={][^"]{7,}"/gi },
];
const slug = name => {
  const s = String(name).replace(/^ANSA\s*\|\s*/i, '');
  const m = s.match(/^(\d+)\.\s*(.*)$/);
  const base = (m ? m[2] : s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  return m ? `${m[1].padStart(2, '0')}-${base}` : base;
};
const KEEP_NODE = ['id', 'name', 'type', 'typeVersion', 'position', 'parameters', 'credentials', 'disabled', 'notes', 'notesInFlow',
                   'executeOnce', 'alwaysOutputData', 'retryOnFail', 'maxTries', 'waitBetweenTries', 'onError', 'continueOnFail', 'webhookId'];
const out = [];
for (const { json: w } of $input.all()) {
  if (!w || !w.id || w.isArchived) continue;
  if ((w.tags || []).some(t => CONFIG.EXCLUDE_TAGS.includes(String(t.name ?? t).toLowerCase()))) continue;   // test flows can hold real document text
  const clean = {
    id: w.id,
    name: w.name,
    nodes: (w.nodes || []).map(n => Object.fromEntries(KEEP_NODE.filter(k => n[k] !== undefined).map(k => [k, n[k]])))
      .sort((a, b) => a.name.localeCompare(b.name)),
    connections: Object.fromEntries(Object.entries(w.connections || {}).sort(([a], [b]) => a.localeCompare(b))),
    settings: w.settings || {},
    tags: (w.tags || []).map(t => t.name ?? t).sort(),
  };
  const text = JSON.stringify(clean, null, 2) + '\n';
  const findings = [];
  for (const p of SENSITIVE) for (const m of text.matchAll(p.re)) {
    if (p.email && CONFIG.ALLOWED_EMAIL_DOMAINS.includes(String(m[1]).toLowerCase())) continue;
    findings.push(`${p.what}: ${m[0].slice(0, 6)}…`);
  }
  out.push({ json: {
    workflow_id: w.id, name: w.name, path: `${CONFIG.PATH}/${slug(w.name)}.json`,
    content: text, blocked: CONFIG.BLOCK_ON_SENSITIVE && findings.length > 0, findings: [...new Set(findings)],
  } });
}
if (!out.length) throw new Error('No workflows returned by the n8n API for the configured tag; nothing to back up');
return out.sort((a, b) => a.json.path.localeCompare(b.json.path));
